        // Live Telemetry Auto-Sync Script
        async function syncLiveIndexTelemetry() {
            try {
                const res = await fetch('http://localhost:8080/telemetry');
                if (!res.ok) return;
                const data = await res.json();
                const tel = data.telemetry || {};

                const cpu = tel.cpu_util || tel.cpu || 0;
                const gpu = tel.gpu_util || tel.gpu || 0;
                const mem = tel.mem_util || tel.memory || 0;
                const net = ((tel.network_io || 0) / (1024 * 1024)).toFixed(1);

                document.getElementById('card-cpu-val').innerText = `${cpu.toFixed(1)}%`;
                document.getElementById('card-cpu-bar').style.width = `${Math.min(100, cpu)}%`;
                document.getElementById('card-cpu-temp').innerText = `${(tel.cpu_temp || 45).toFixed(1)}°C`;
                document.getElementById('card-fan-rpm').innerText = `${Math.round(data.target_rpm || 1000)} RPM`;

